arguments.command:
cd /tmp
# Try dynamic symbols for the SGen worker addresses that didn't resolve well
for addr in 0x2f4b20 0x2f4c84; do
  echo "=== $addr ==="
  # Use nm to find the nearest symbol
  nm libmonosgen-2.0.so.dbg 2>/dev/null | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name = "??"; best_addr = 0 }
    /^[0-9a-f]+ [tTwW]/ {
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= target_dec && sym_addr > best_addr) {
        best_addr = sym_addr
        best_name = $3
      }
    }
    END { printf "%s+0x%x\n", best_name, target_dec - best_addr }
  '
done

