arguments.command:
cd /tmp
# These addresses are likely in a data/jump table area. Let's check what section they're in
readelf -S libmonosgen-2.0.so.dbg 2>/dev/null | awk '
  /\[/ { 
    if ($4 != "" && $5 != "") {
      name=$2; addr=strtonum("0x"$4); size=strtonum("0x"$6);
      if (0x2f4b20 >= addr && 0x2f4b20 < addr+size) print "0x2f4b20 in section " name " (addr=" $4 " size=" $6 ")"
    }
  }'
# Try using the symtab instead
nm libmonosgen-2.0.so.dbg 2>/dev/null | grep -v '^\$' | awk '
  /^[0-9a-f]+ [tT]/ {
    addr = strtonum("0x" $1)
    if (addr >= 0x2e0000 && addr <= 0x300000) print
  }' | sort | awk -v t1=0x2f4b20 -v t2=0x2f4c84 '
  BEGIN { t1d=strtonum(t1); t2d=strtonum(t2) }
  {
    addr = strtonum("0x" $1)
    if (addr <= t1d) { prev1 = $0; paddr1 = addr }
    if (addr <= t2d) { prev2 = $0; paddr2 = addr }
    if (addr > t1d && !found1) { printf "0x2f4b20 -> %s +0x%x (next: %s)\n", prev1, t1d-paddr1, $0; found1=1 }
    if (addr > t2d && !found2) { printf "0x2f4c84 -> %s +0x%x (next: %s)\n", prev2, t2d-paddr2, $0; found2=1 }
  }'

