arguments.command:
cd /tmp
# 0x2f4b20 and 0x2f4c84 fall in RW data segment (>0x2ef810 which is end of text)
# These are likely unreliable unwind frames. Let's check dynamic symbols near these anyway.
nm -D libmonosgen-2.0.so 2>/dev/null | awk '{
  addr = strtonum("0x" $1)
  if (addr >= 0x2f3000 && addr <= 0x2f6000) print
}' | head -20
echo "=== Checking closest functions ==="
nm -D libmonosgen-2.0.so 2>/dev/null | awk '
  /^[0-9a-f]+ [TtWw]/ {
    addr = strtonum("0x" $1)
    if (addr <= 0x2f4b20) { pa=$1; pn=$3 }
  }
  END { print "nearest function to 0x2f4b20: " pn " @ 0x" pa }'

